<script setup lang="ts">import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import axios from 'axios';const props=defineProps<{id:string}>();const router=useRouter();const identity=localStorage.getItem('username')||'教师';const logout=()=>{localStorage.clear();router.replace('/login')};const data=ref<any>({participants:0,submitted:0});async function load(){const r=await axios.get(`/api/v1/teacher/exams/${props.id}/dashboard`);data.value=r.data}async function end(){if(confirm('确定强制结束全场考试？系统将立即对所有未交卷学生触发自动交卷，且无法撤销！'))await axios.post(`/api/v1/teacher/exams/${props.id}/force-end`)}onMounted(load);setInterval(load,5000)</script>
<template><main><header><h1>考场实时监控中心</h1><span>教师：{{identity}} <button @click="logout">退出登录</button></span></header><p>考试名称：LabProctor 模拟考试</p><p>机房白名单网段：127.0.0.1/32、192.168.0.0/16、10.0.0.0/8</p><div class="cards"><b>在线总人数 / 考场总人数：{{data.submitted}} / {{data.participants}}</b><b>已交卷：{{data.submitted}}</b></div><table><thead><tr><th>学号</th><th>姓名</th><th>所属班级</th><th>当前 IP</th><th>在线状态</th><th>登录时间</th><th>切屏次数</th><th>累计离开时长</th><th>交卷时间</th><th>操作</th></tr></thead><tbody><tr><td colspan="10">学生实时状态由服务端监控接口提供，当前暂无详细名单数据。</td></tr></tbody></table><button class="danger" @click="end">🛑 强制结束整场考试</button></main></template><style scoped>main{padding:32px;font:16px system-ui}header{display:flex;justify-content:space-between;align-items:center}.cards{display:flex;gap:30px;margin:20px 0}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:10px;border:1px solid #ddd}.danger{margin-top:20px;background:#b42318;color:white;padding:12px;border:0;border-radius:5px}button{padding:8px 12px;border:0;border-radius:5px;cursor:pointer}</style>
